-- Import of PF 2025 official exam items for the career "Agente de Polícia
-- Federal" (Edital nº 1 - PF - Policial, de 20 de maio de 2025, retificado
-- pelo Edital nº 9 de 16/09/2025, CONCURSO PÚBLICO APLICAÇÃO: 27/07/2025,
-- banca CEBRASPE, para provimento de vagas nos cargos de Delegado de
-- Polícia Federal, Perito Criminal Federal, Escrivão de Polícia Federal,
-- Agente de Polícia Federal e Papiloscopista Policial Federal). This is a
-- new exam_year (2025) distinct from the PF 2021 imports already in the
-- database (20260926050000/20260927080000 Agente, 20260929240000 Delegado,
-- 20260929250000 Escrivão, 20260929260000 Papiloscopista).
--
-- The 120-item objective test for cargo Agente is made up of three shared
-- booklets read verbatim from Google Drive this session:
--   - CB2 (Conhecimentos Básicos - Bloco I, itens 1-60, shared with cargos
--     15/16/17): 106_PF_CB2_01.pdf, fileId 1oYY4L2FMusSyNcMxoegVSD3GrMndqTm3.
--     Gabarito: 106_PF_25_GabaritosDefinitivos (CB2), fileId
--     1ok6hmVmB1AmARAz-n8P6paBKSIXUphq6.
--   - CG1 (Conhecimentos Básicos - Bloco II, itens 61-96, Informática,
--     shared with cargos 15/16/17): 106_PF_CG1_01.pdf, fileId
--     1sSrIZQq0hR50td0UcNlsDK1fnpmTxV3Q. Gabarito: fileId
--     15rFd8qPjUeikGc_bty6HzDAQF5b6qVOr.
--   - Prova específica Agente (Conhecimentos Específicos - Bloco III,
--     itens 97-120, Contabilidade Geral): 106_PF_016_01.pdf, fileId
--     1w4FShvtPjBnmeHDQx1p6-9S_U5-h2vZB (cover states "CARGO 16: AGENTE DE
--     POLÍCIA FEDERAL" on the gabarito). Gabarito: fileId
--     1en2ktaK9eFYs0BycLbKkqR3Y2BPuORY0.
--
-- content_sources url values are the canonical Google Drive file view URLs
-- for the CB2/CG1 fileIds (https://drive.google.com/file/d/<fileId>/view),
-- deliberately shared with the parallel Escrivão/Papiloscopista 2025
-- imports so that on-conflict (url) matches the same rows instead of
-- creating duplicates for the shared CB2/CG1 booklets.
--
-- The unique constraint official_exam_questions_contest_career_year_item_key
-- = (contest_name,career_name,exam_year,item_number) already exists (added
-- by 20260929240000_pf_2021_delegado_import.sql) and already distinguishes
-- career_name, so no ALTER TABLE is needed: ('Polícia Federal','Agente de
-- Polícia Federal',2025,item_number) is a new, non-colliding key.

insert into public.content_sources (source_type,title,issuer,url,status,notes) values
('outro','Prova objetiva PF 2025 - Bloco I Comum (CB2)','Polícia Federal / CEBRASPE','https://drive.google.com/file/d/1oYY4L2FMusSyNcMxoegVSD3GrMndqTm3/view','vigente','Caderno oficial 106_PF_CB2_01, Conhecimentos Básicos Bloco I (itens 1-60), comum aos cargos 15/16/17 do Edital nº 1 - PF - Policial de 2025 (Google Drive fileId 1oYY4L2FMusSyNcMxoegVSD3GrMndqTm3, texto lido verbatim nesta sessão).'),
('outro','Gabarito definitivo PF 2025 - Bloco I Comum (CB2)','Polícia Federal / CEBRASPE','https://drive.google.com/file/d/1ok6hmVmB1AmARAz-n8P6paBKSIXUphq6/view','vigente','Gabarito oficial definitivo 106_PF_CB2_01, Conhecimentos Básicos Bloco I (itens 1-60) (Google Drive fileId 1ok6hmVmB1AmARAz-n8P6paBKSIXUphq6); X identifica item anulado.'),
('outro','Prova objetiva PF 2025 - Bloco II Comum TI (CG1)','Polícia Federal / CEBRASPE','https://drive.google.com/file/d/1sSrIZQq0hR50td0UcNlsDK1fnpmTxV3Q/view','vigente','Caderno oficial 106_PF_CG1_01, Conhecimentos Básicos Bloco II - Informática (itens 61-96), comum aos cargos 15/16/17 do Edital nº 1 - PF - Policial de 2025 (Google Drive fileId 1sSrIZQq0hR50td0UcNlsDK1fnpmTxV3Q, texto lido verbatim nesta sessão).'),
('outro','Gabarito definitivo PF 2025 - Bloco II Comum TI (CG1)','Polícia Federal / CEBRASPE','https://drive.google.com/file/d/15rFd8qPjUeikGc_bty6HzDAQF5b6qVOr/view','vigente','Gabarito oficial definitivo 106_PF_CG1_01, Conhecimentos Básicos Bloco II - Informática (itens 61-96) (Google Drive fileId 15rFd8qPjUeikGc_bty6HzDAQF5b6qVOr); X identifica item anulado.'),
('outro','Prova objetiva PF 2025 - Agente de Polícia Federal (específica)','Polícia Federal / CEBRASPE','https://drive.google.com/file/d/1w4FShvtPjBnmeHDQx1p6-9S_U5-h2vZB/view','vigente','Caderno oficial 106_PF_016_01, Conhecimentos Específicos Bloco III do cargo Agente de Polícia Federal (itens 97-120, Contabilidade Geral) (Google Drive fileId 1w4FShvtPjBnmeHDQx1p6-9S_U5-h2vZB, texto lido verbatim nesta sessão).'),
('outro','Gabarito definitivo PF 2025 - Agente de Polícia Federal (específica)','Polícia Federal / CEBRASPE','https://drive.google.com/file/d/1en2ktaK9eFYs0BycLbKkqR3Y2BPuORY0/view','vigente','Gabarito oficial definitivo 106_PF_016_01, explicitamente rotulado CARGO 16: AGENTE DE POLÍCIA FEDERAL (Google Drive fileId 1en2ktaK9eFYs0BycLbKkqR3Y2BPuORY0); X identifica item anulado.')
on conflict (url) do update set checked_at=now(),status=excluded.status,notes=excluded.notes;

-- New syllabus edition for this career/year.
insert into public.syllabus_editions (contest_name,role_name,contest_year,exam_board,source_id)
select 'Polícia Federal','Agente de Polícia Federal',2025,'CEBRASPE',(select id from public.content_sources where url=$q$https://drive.google.com/file/d/1oYY4L2FMusSyNcMxoegVSD3GrMndqTm3/view$q$)
where not exists (
  select 1 from public.syllabus_editions
  where contest_name='Polícia Federal' and role_name='Agente de Polícia Federal' and contest_year=2025
);

-- Discipline breakdown derived directly from reading each prova's own
-- section command blocks: Língua Portuguesa (1-8, texto sobre narrativas
-- policiais), Redação Oficial (9-10), Direito Administrativo (11-16),
-- Direitos e Garantias Fundamentais / Forma e Sistema de Governo (17-18),
-- Direito Constitucional - Segurança Pública, Indígenas e Meio Ambiente
-- (19-22), Direito Penal (23-25 e 28, CP e jurisprudência do STJ, lei penal
-- no espaço), Direito Processual Penal (26-27, inquérito policial), Direitos
-- Humanos (29-32, Regras de Mandela), Direito Internacional (33-34,
-- Convenção dos Refugiados e Convenção contra a Tortura), Legislação Penal
-- Especial (35-39, ECA, Lei de Drogas, Lei de Tortura, Lei de Migração),
-- Legislação Especial de Segurança Pública e Identificação Civil (40-44,
-- Estatuto do Desarmamento, Lei de Crimes Ambientais, Lei 10.446/2002,
-- Decreto 11.797/2023), Estatística e Probabilidade (45-52), Raciocínio
-- Lógico-Matemático (53-60), Informática (61-96, bloco CG1 completo:
-- Internet/intranet, redes, segurança, nuvem, TGS, banco de dados, Python,
-- machine learning, DNS, Linux, API) e Contabilidade Geral (97-120, bloco
-- específico do cargo Agente: patrimônio/atos e fatos administrativos,
-- escrituração contábil, balancete, balanço patrimonial e DRE,
-- contabilização de operações, CPC 00 (R2)).
with edition as (
  select id from public.syllabus_editions
  where contest_name='Polícia Federal' and role_name='Agente de Polícia Federal' and contest_year=2025
)
insert into public.syllabus_topics (edition_id,block_name,discipline,topic_order,topic_text,content_status)
select edition.id,'Prova objetiva',d.discipline,1,d.topic_text,'current'
from edition cross join (values
  ('Língua Portuguesa','Compreensão e interpretação de texto sobre narrativas policiais na literatura, no cinema e na televisão; propriedades linguísticas, vocabulário, coesão e regência do texto.'),
  ('Redação Oficial','Manual de Redação da Presidência da República: impessoalidade dos expedientes oficiais e emprego dos pronomes de tratamento.'),
  ('Direito Administrativo','Atributos dos atos administrativos, responsabilidade civil do Estado, sociedades de economia mista e empresas públicas, penalidades disciplinares e inexigibilidade de licitação.'),
  ('Direitos e Garantias Fundamentais e Formas de Governo','Sigilo das comunicações e distinção entre forma de governo e sistema de governo.'),
  ('Direito Constitucional - Segurança Pública, Indígenas e Meio Ambiente','Atribuições constitucionais da Polícia Federal e da Polícia Rodoviária Federal, responsabilidade penal da pessoa jurídica por crimes ambientais e mineração em terras indígenas (CF/1988).'),
  ('Direito Penal','Crime de prevaricação, causas de aumento de pena no roubo, qualificadoras do furto e aplicação da lei penal no espaço, à luz do CP e da jurisprudência do STJ.'),
  ('Direito Processual Penal','Instauração do inquérito policial.'),
  ('Direitos Humanos','Regras Mínimas das Nações Unidas para o Tratamento de Reclusos (Regras de Mandela).'),
  ('Direito Internacional','Convenção Relativa ao Estatuto dos Refugiados e Convenção contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes.'),
  ('Legislação Penal Especial','Lei nº 8.069/1990 (ECA), Lei nº 11.343/2006 (Drogas), Lei nº 9.455/1997 (Tortura) e Lei nº 13.445/2017 (Lei de Migração).'),
  ('Legislação Especial de Segurança Pública e Identificação Civil','Lei nº 10.826/2003 (Estatuto do Desarmamento), Lei nº 9.605/1998 (Crimes Ambientais), Lei nº 10.446/2002 e Lei nº 7.116/1983 c/c Decreto nº 11.797/2023 (identificação civil e Serviço de Identificação do Cidadão).'),
  ('Estatística e Probabilidade','Distribuição normal, soma de variáveis aleatórias, distribuição binomial, correlação de Pearson, regressão linear simples e intervalo de confiança.'),
  ('Raciocínio Lógico-Matemático','Tabela-verdade, lógica de argumentação, proposições condicionais, análise combinatória e princípio da inclusão-exclusão.'),
  ('Informática','Internet e intranet, redes de computadores, segurança da informação, computação em nuvem, teoria geral de sistemas, banco de dados e modelo entidade-relacionamento, mineração de dados e Big Data, modelo OSI, linguagem Python, biometria (FPIR/FNIR), machine learning, sistema operacional Linux, protocolo DNS, autenticação multifator, transações ACID e API (REST/GraphQL).'),
  ('Contabilidade Geral','Patrimônio, atos e fatos administrativos, contas e plano de contas, escrituração contábil, regime de competência, balancete de verificação, balanço patrimonial, demonstração do resultado do exercício, depreciação, provisões e Estrutura Conceitual do CPC 00 (R2).')
) d(discipline,topic_text)
on conflict (edition_id,discipline,topic_order) do update set topic_text=excluded.topic_text;

with imported(exam_year,item_number,subject,question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,context_review_required,review_note,source_block) as (values
(2025,1,$q$Língua Portuguesa$q$,$q$O texto sugere que o gênero policial é o preferido do público na literatura, na televisão e no cinema.$q$,$q$O texto sugere que o gênero policial é o preferido do público na literatura, na televisão e no cinema.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,2,$q$Língua Portuguesa$q$,$q$Entende-se da leitura do texto que a frequente transposição da narrativa de best-sellers para as telas da televisão e do cinema se justifica pela expectativa de repetição do sucesso obtido na venda das respectivas obras literárias.$q$,$q$Entende-se da leitura do texto que a frequente transposição da narrativa de best-sellers para as telas da televisão e do cinema se justifica pela expectativa de repetição do sucesso obtido na venda das respectivas obras literárias.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,3,$q$Língua Portuguesa$q$,$q$A partir das ideias de Carlos Gerbase reproduzidas no texto, conclui-se que as histórias narradas em livros e filmes podem nortear a conduta social de leitores e espectadores.$q$,$q$A partir das ideias de Carlos Gerbase reproduzidas no texto, conclui-se que as histórias narradas em livros e filmes podem nortear a conduta social de leitores e espectadores.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,4,$q$Língua Portuguesa$q$,$q$O termo "crescente" (segundo período do primeiro parágrafo) poderia ser substituído, sem prejuízo do sentido original do texto, por considerável.$q$,$q$O termo "crescente" (segundo período do primeiro parágrafo) poderia ser substituído, sem prejuízo do sentido original do texto, por considerável.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,5,$q$Língua Portuguesa$q$,$q$No segundo período do segundo parágrafo, a oração "que as histórias têm começo, meio e fim" classifica-se sintaticamente como subordinada adjetiva restritiva.$q$,$q$No segundo período do segundo parágrafo, a oração "que as histórias têm começo, meio e fim" classifica-se sintaticamente como subordinada adjetiva restritiva.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,6,$q$Língua Portuguesa$q$,$q$A supressão da vírgula empregada após "personagem" (primeiro período do terceiro parágrafo) prejudicaria a correção gramatical do texto.$q$,$q$A supressão da vírgula empregada após "personagem" (primeiro período do terceiro parágrafo) prejudicaria a correção gramatical do texto.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,7,$q$Língua Portuguesa$q$,$q$No segundo parágrafo, o intercambiamento das expressões "Logo" (terceiro período) e "Além disso" (quarto período), embora alterasse as relações coesivas entre os períodos, manteria a coerência das ideias do texto.$q$,$q$No segundo parágrafo, o intercambiamento das expressões "Logo" (terceiro período) e "Além disso" (quarto período), embora alterasse as relações coesivas entre os períodos, manteria a coerência das ideias do texto.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,8,$q$Língua Portuguesa$q$,$q$O pronome presente no termo "nela" (último parágrafo) tem como referente "a narrativa policial".$q$,$q$O pronome presente no termo "nela" (último parágrafo) tem como referente "a narrativa policial".$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,9,$q$Redação Oficial$q$,$q$Os assuntos objetos dos expedientes oficiais devem ser tratados de forma estritamente impessoal, uma vez que a redação oficial é elaborada sempre em nome do serviço público e em atendimento ao interesse geral dos cidadãos.$q$,$q$Os assuntos objetos dos expedientes oficiais devem ser tratados de forma estritamente impessoal, uma vez que a redação oficial é elaborada sempre em nome do serviço público e em atendimento ao interesse geral dos cidadãos.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,10,$q$Redação Oficial$q$,$q$Na redação oficial, os pronomes de tratamento são empregados em três contextos: endereçamento, vocativo e corpo do texto.$q$,$q$Na redação oficial, os pronomes de tratamento são empregados em três contextos: endereçamento, vocativo e corpo do texto.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,11,$q$Direito Administrativo$q$,$q$A presunção de veracidade dos atos administrativos refere-se aos fatos, ou seja, presumem-se verdadeiros os fatos alegados pela administração pública, ao passo que a autoexecutoriedade constitui atributo pelo qual os atos administrativos se impõem a terceiros, independentemente de sua concordância.$q$,$q$A presunção de veracidade dos atos administrativos refere-se aos fatos, ou seja, presumem-se verdadeiros os fatos alegados pela administração pública, ao passo que a autoexecutoriedade constitui atributo pelo qual os atos administrativos se impõem a terceiros, independentemente de sua concordância.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,12,$q$Direito Administrativo$q$,$q$A pessoa que sofrer algum dano por ato praticado por um servidor público no exercício da função poderá ajuizar ação de indenização somente contra o Estado.$q$,$q$A pessoa que sofrer algum dano por ato praticado por um servidor público no exercício da função poderá ajuizar ação de indenização somente contra o Estado.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,13,$q$Direito Administrativo$q$,$q$As sociedades de economia mista e as empresas públicas desempenham atividade de natureza econômica e se distinguem pela forma de organização e pela composição do capital.$q$,$q$As sociedades de economia mista e as empresas públicas desempenham atividade de natureza econômica e se distinguem pela forma de organização e pela composição do capital.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,14,$q$Direito Administrativo$q$,$q$O cancelamento do registro da penalidade de suspensão de servidor público, que ocorre após o decurso de dois anos de efetivo exercício, surtirá efeitos retroativos caso o servidor não pratique, nesse período, nova infração disciplinar.$q$,$q$O cancelamento do registro da penalidade de suspensão de servidor público, que ocorre após o decurso de dois anos de efetivo exercício, surtirá efeitos retroativos caso o servidor não pratique, nesse período, nova infração disciplinar.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,15,$q$Direito Administrativo$q$,$q$É inexigível a licitação para a contratação que possa acarretar comprometimento da segurança nacional, nos casos estabelecidos pelo Ministério da Defesa, mediante demanda dos comandos das Forças Armadas.$q$,$q$É inexigível a licitação para a contratação que possa acarretar comprometimento da segurança nacional, nos casos estabelecidos pelo Ministério da Defesa, mediante demanda dos comandos das Forças Armadas.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,16,$q$Direito Administrativo$q$,$q$O princípio da razoabilidade é considerado um princípio implícito da administração pública e se baseia naquilo que se situa dentro de limites aceitáveis.$q$,$q$O princípio da razoabilidade é considerado um princípio implícito da administração pública e se baseia naquilo que se situa dentro de limites aceitáveis.$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,17,$q$Direitos e Garantias Fundamentais e Formas de Governo$q$,$q$O sigilo da correspondência e das comunicações telefônicas pode ser afastado por determinação judicial, quando isso for necessário à apuração de infrações penais ou administrativas, conforme dispuser a lei.$q$,$q$O sigilo da correspondência e das comunicações telefônicas pode ser afastado por determinação judicial, quando isso for necessário à apuração de infrações penais ou administrativas, conforme dispuser a lei.$q$,'E',2,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,18,$q$Direitos e Garantias Fundamentais e Formas de Governo$q$,$q$A forma de governo diz respeito à relação entre os Poderes Executivo e Legislativo, ao passo que o sistema de governo refere-se à origem e à titularidade do poder político.$q$,$q$A forma de governo diz respeito à relação entre os Poderes Executivo e Legislativo, ao passo que o sistema de governo refere-se à origem e à titularidade do poder político.$q$,'E',2,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,19,$q$Direito Constitucional - Segurança Pública, Indígenas e Meio Ambiente$q$,$q$Cabe à Polícia Federal exercer, com exclusividade, as funções de polícia judiciária da União, dos estados e do Distrito Federal.$q$,$q$Cabe à Polícia Federal exercer, com exclusividade, as funções de polícia judiciária da União, dos estados e do Distrito Federal.$q$,'E',2,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,20,$q$Direito Constitucional - Segurança Pública, Indígenas e Meio Ambiente$q$,$q$Além das pessoas físicas, as pessoas jurídicas também podem ser responsabilizadas penalmente pela prática de crimes ambientais.$q$,$q$Além das pessoas físicas, as pessoas jurídicas também podem ser responsabilizadas penalmente pela prática de crimes ambientais.$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,21,$q$Direito Constitucional - Segurança Pública, Indígenas e Meio Ambiente$q$,$q$A pesquisa e a lavra de minerais em terras indígenas só podem ser efetivadas mediante autorização do Congresso Nacional.$q$,$q$A pesquisa e a lavra de minerais em terras indígenas só podem ser efetivadas mediante autorização do Congresso Nacional.$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,22,$q$Direito Constitucional - Segurança Pública, Indígenas e Meio Ambiente$q$,$q$O patrulhamento ostensivo das ferrovias federais compete à Polícia Rodoviária Federal.$q$,$q$O patrulhamento ostensivo das ferrovias federais compete à Polícia Rodoviária Federal.$q$,'E',2,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,23,$q$Direito Penal$q$,$q$O crime de prevaricação exige, além da conduta típica de retardar, deixar de praticar ou praticar indevidamente ato de ofício, o dolo específico de satisfazer interesse ou sentimento pessoal, não sendo suficiente a constatação de mera negligência ou descompromisso funcional.$q$,$q$O crime de prevaricação exige, além da conduta típica de retardar, deixar de praticar ou praticar indevidamente ato de ofício, o dolo específico de satisfazer interesse ou sentimento pessoal, não sendo suficiente a constatação de mera negligência ou descompromisso funcional.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,24,$q$Direito Penal$q$,$q$O uso de um cabo de vassoura contra a vítima durante a prática de roubo pode justificar a aplicação da causa de aumento de pena prevista no art. 157, § 2.º, VII, do CP, desde que comprovada sua potencialidade lesiva, ainda que não haja perícia ou apreensão do objeto.$q$,$q$O uso de um cabo de vassoura contra a vítima durante a prática de roubo pode justificar a aplicação da causa de aumento de pena prevista no art. 157, § 2.º, VII, do CP, desde que comprovada sua potencialidade lesiva, ainda que não haja perícia ou apreensão do objeto.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,25,$q$Direito Penal$q$,$q$Considere que um casal tenha sido preso em flagrante enquanto furtava cabos de energia elétrica em via pública: a mulher encontrava-se ao lado do poste de energia com uma mochila onde estavam armazenados diversos metros de fios já cortados e perto dela havia um facão utilizado para o corte; o homem se encontrava no alto do poste, com o facão em mãos, em plena retirada de novos cabos. Nessa situação, a ausência de laudo pericial sobre o local e os meios utilizados impede, em relação à mulher, a configuração da qualificadora da escalada no crime de furto, ainda que policiais tenham presenciado diretamente a prática delitiva e narrado detalhadamente os fatos.$q$,$q$Considere que um casal tenha sido preso em flagrante enquanto furtava cabos de energia elétrica em via pública: a mulher encontrava-se ao lado do poste de energia com uma mochila onde estavam armazenados diversos metros de fios já cortados e perto dela havia um facão utilizado para o corte; o homem se encontrava no alto do poste, com o facão em mãos, em plena retirada de novos cabos. Nessa situação, a ausência de laudo pericial sobre o local e os meios utilizados impede, em relação à mulher, a configuração da qualificadora da escalada no crime de furto, ainda que policiais tenham presenciado diretamente a prática delitiva e narrado detalhadamente os fatos.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,26,$q$Direito Processual Penal$q$,$q$O inquérito policial poderá ser iniciado mediante requerimento do ofendido, mesmo nos crimes de ação pública incondicionada.$q$,$q$O inquérito policial poderá ser iniciado mediante requerimento do ofendido, mesmo nos crimes de ação pública incondicionada.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,27,$q$Direito Processual Penal$q$,$q$A autoridade policial deve instaurar inquérito policial sempre que qualquer pessoa do povo comunicar, verbalmente ou por escrito, a ocorrência de uma infração penal, independentemente da natureza da ação penal ou da verificação da procedência das informações.$q$,$q$A autoridade policial deve instaurar inquérito policial sempre que qualquer pessoa do povo comunicar, verbalmente ou por escrito, a ocorrência de uma infração penal, independentemente da natureza da ação penal ou da verificação da procedência das informações.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,28,$q$Direito Penal$q$,$q$Durante operação de fiscalização em águas internacionais (alto-mar), uma embarcação brasileira de propriedade privada foi flagrada transportando substâncias entorpecentes. As autoridades estrangeiras permitiram que o Brasil conduzisse a investigação e eventual processo criminal, já que a embarcação estava registrada no Brasil. Com base na situação hipotética precedente e no disposto no CP: Como o crime ocorreu fora do território brasileiro, em alto-mar, e não envolveu embarcação pública, a lei penal brasileira não pode ser aplicada ao caso.$q$,$q$Durante operação de fiscalização em águas internacionais (alto-mar), uma embarcação brasileira de propriedade privada foi flagrada transportando substâncias entorpecentes. As autoridades estrangeiras permitiram que o Brasil conduzisse a investigação e eventual processo criminal, já que a embarcação estava registrada no Brasil. Com base na situação hipotética precedente e no disposto no CP: Como o crime ocorreu fora do território brasileiro, em alto-mar, e não envolveu embarcação pública, a lei penal brasileira não pode ser aplicada ao caso.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,29,$q$Direitos Humanos$q$,$q$Na admissão de indivíduos em estabelecimentos prisionais, deverá ser adicionado, no sistema de registro do recluso, inventário dos seus bens pessoais.$q$,$q$Na admissão de indivíduos em estabelecimentos prisionais, deverá ser adicionado, no sistema de registro do recluso, inventário dos seus bens pessoais.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,30,$q$Direitos Humanos$q$,$q$As Regras de Mandela contemplam a possibilidade de se impor ao recluso a realização de trabalho no estabelecimento prisional em cumprimento de qualquer medida disciplinar.$q$,$q$As Regras de Mandela contemplam a possibilidade de se impor ao recluso a realização de trabalho no estabelecimento prisional em cumprimento de qualquer medida disciplinar.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,31,$q$Direitos Humanos$q$,$q$A separação de categorias de pessoas presas deve orientar-se por critérios de gênero, idade e natureza dos delitos, não havendo regra que determine a separação dos presos em razão da natureza da detenção, isto é, se preventiva ou se oriunda de condenação definitiva.$q$,$q$A separação de categorias de pessoas presas deve orientar-se por critérios de gênero, idade e natureza dos delitos, não havendo regra que determine a separação dos presos em razão da natureza da detenção, isto é, se preventiva ou se oriunda de condenação definitiva.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,32,$q$Direitos Humanos$q$,$q$Qualquer pessoa declarada culpada por um delito terá o direito de recorrer a uma instância superior para rever a sentença condenatória que lhe tenha sido imposta e a pena que lhe tenha sido aplicada.$q$,$q$Qualquer pessoa declarada culpada por um delito terá o direito de recorrer a uma instância superior para rever a sentença condenatória que lhe tenha sido imposta e a pena que lhe tenha sido aplicada.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,33,$q$Direito Internacional$q$,$q$Os Estados-partes da Convenção contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes devem incluir os atos de tortura como crimes extraditáveis em todos os tratados de extradição que vierem a concluir entre si.$q$,$q$Os Estados-partes da Convenção contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes devem incluir os atos de tortura como crimes extraditáveis em todos os tratados de extradição que vierem a concluir entre si.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,34,$q$Direito Internacional$q$,$q$A Convenção Relativa ao Estatuto dos Refugiados veda aos Estados contratantes, em qualquer circunstância, a expulsão de refugiados.$q$,$q$A Convenção Relativa ao Estatuto dos Refugiados veda aos Estados contratantes, em qualquer circunstância, a expulsão de refugiados.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,35,$q$Legislação Penal Especial$q$,$q$O pedido do Ministério Público para aplicação de medida socioeducativa deverá ser julgado improcedente pela autoridade judiciária nas seguintes hipóteses: comprovação da inexistência do fato; ausência de prova da existência do fato; não caracterização do fato como ato infracional; e falta de prova da participação do adolescente no ato infracional.$q$,$q$O pedido do Ministério Público para aplicação de medida socioeducativa deverá ser julgado improcedente pela autoridade judiciária nas seguintes hipóteses: comprovação da inexistência do fato; ausência de prova da existência do fato; não caracterização do fato como ato infracional; e falta de prova da participação do adolescente no ato infracional.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,36,$q$Legislação Especial de Segurança Pública e Identificação Civil$q$,$q$No âmbito da segurança privada, compete à Polícia Federal renovar, a cada dois anos, a autorização de funcionamento das empresas de monitoramento de sistemas eletrônicos de segurança que atuam, simultaneamente, em mais de um estado da Federação.$q$,$q$No âmbito da segurança privada, compete à Polícia Federal renovar, a cada dois anos, a autorização de funcionamento das empresas de monitoramento de sistemas eletrônicos de segurança que atuam, simultaneamente, em mais de um estado da Federação.$q$,'X',1,'annulled',true,false,$q$Item anulado no gabarito oficial definitivo (106_PF_CB2_01); não é exibido aos estudantes.$q$,'CB2'),
(2025,37,$q$Legislação Penal Especial$q$,$q$Segundo a Lei de Migração, desde que exista disposição específica em tratado, o pedido de prisão cautelar poderá ser transmitido à autoridade competente para extradição no Brasil, mediante canal estabelecido com o ponto focal da INTERPOL no país, devidamente instruído com a documentação comprobatória da existência de ordem de prisão proferida por Estado estrangeiro.$q$,$q$Segundo a Lei de Migração, desde que exista disposição específica em tratado, o pedido de prisão cautelar poderá ser transmitido à autoridade competente para extradição no Brasil, mediante canal estabelecido com o ponto focal da INTERPOL no país, devidamente instruído com a documentação comprobatória da existência de ordem de prisão proferida por Estado estrangeiro.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,38,$q$Legislação Penal Especial$q$,$q$A apreensão dos meios de transporte e dos maquinários, utensílios, instrumentos e objetos de qualquer natureza utilizados para a prática, habitual ou não, do tráfico ilícito de drogas deve ser imediatamente comunicada pela autoridade de polícia judiciária responsável pela investigação ao juízo competente, que, no prazo de trinta dias, contado dessa comunicação, deve determinar a alienação dos bens apreendidos, excetuadas as armas.$q$,$q$A apreensão dos meios de transporte e dos maquinários, utensílios, instrumentos e objetos de qualquer natureza utilizados para a prática, habitual ou não, do tráfico ilícito de drogas deve ser imediatamente comunicada pela autoridade de polícia judiciária responsável pela investigação ao juízo competente, que, no prazo de trinta dias, contado dessa comunicação, deve determinar a alienação dos bens apreendidos, excetuadas as armas.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,39,$q$Legislação Penal Especial$q$,$q$O condenado por crime de tortura, bem como aquele que se houver omitido em face das condutas que o caracterizam quando tinha o dever de evitá-las ou apurá-las, iniciará o cumprimento da pena em regime fechado.$q$,$q$O condenado por crime de tortura, bem como aquele que se houver omitido em face das condutas que o caracterizam quando tinha o dever de evitá-las ou apurá-las, iniciará o cumprimento da pena em regime fechado.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,40,$q$Legislação Especial de Segurança Pública e Identificação Civil$q$,$q$A carteira de identidade fará prova de todos os dados nela incluídos, dispensando a apresentação dos documentos que lhe deram origem ou que nela tenham sido mencionados.$q$,$q$A carteira de identidade fará prova de todos os dados nela incluídos, dispensando a apresentação dos documentos que lhe deram origem ou que nela tenham sido mencionados.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,41,$q$Legislação Especial de Segurança Pública e Identificação Civil$q$,$q$No âmbito do Serviço de Identificação do Cidadão, compete à Polícia Federal definir especificações técnicas de documentos de segurança vinculados à identificação de pessoas naturais e regulamentar o procedimento a ser adotado em caso de divergência na verificação dos dados da pessoa natural.$q$,$q$No âmbito do Serviço de Identificação do Cidadão, compete à Polícia Federal definir especificações técnicas de documentos de segurança vinculados à identificação de pessoas naturais e regulamentar o procedimento a ser adotado em caso de divergência na verificação dos dados da pessoa natural.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,42,$q$Legislação Especial de Segurança Pública e Identificação Civil$q$,$q$Quando houver repercussão interestadual ou internacional que exija repressão uniforme, poderá o Departamento de Polícia Federal do Ministério da Justiça, sem prejuízo da responsabilidade dos órgãos de segurança pública arrolados na Constituição Federal de 1988, proceder à investigação de quaisquer crimes praticados por meio da rede mundial de computadores que difundam conteúdo misógino, definido como aquele que propaga ódio ou aversão às mulheres.$q$,$q$Quando houver repercussão interestadual ou internacional que exija repressão uniforme, poderá o Departamento de Polícia Federal do Ministério da Justiça, sem prejuízo da responsabilidade dos órgãos de segurança pública arrolados na Constituição Federal de 1988, proceder à investigação de quaisquer crimes praticados por meio da rede mundial de computadores que difundam conteúdo misógino, definido como aquele que propaga ódio ou aversão às mulheres.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,43,$q$Legislação Especial de Segurança Pública e Identificação Civil$q$,$q$Pratica crime o proprietário de empresa de segurança e transporte de valores que, nas primeiras 24 horas depois de sofrer perda, furto, roubo ou outra forma de extravio de arma de fogo, acessório ou munição que estejam sob sua guarda, deixa de registrar ocorrência policial e de comunicar o fato à Polícia Federal.$q$,$q$Pratica crime o proprietário de empresa de segurança e transporte de valores que, nas primeiras 24 horas depois de sofrer perda, furto, roubo ou outra forma de extravio de arma de fogo, acessório ou munição que estejam sob sua guarda, deixa de registrar ocorrência policial e de comunicar o fato à Polícia Federal.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,44,$q$Legislação Especial de Segurança Pública e Identificação Civil$q$,$q$Nas infrações penais derivadas de condutas e atividades lesivas ao meio ambiente, a ação penal é pública incondicionada.$q$,$q$Nas infrações penais derivadas de condutas e atividades lesivas ao meio ambiente, a ação penal é pública incondicionada.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$,'CB2'),
(2025,45,$q$Estatística e Probabilidade$q$,$q$Considerando que de uma população X que se distribui conforme uma distribuição normal com média μ e variância σ² foi retirada uma amostra aleatória simples de tamanho n = 4, denotada como X1,X2,X3,X4, e a soma S = X1+X2+X3+X4: A mediana de S é igual a (X2+X3)/2.$q$,$q$Considerando que de uma população X que se distribui conforme uma distribuição normal com média μ e variância σ² foi retirada uma amostra aleatória simples de tamanho n = 4, denotada como X1,X2,X3,X4, e a soma S = X1+X2+X3+X4: A mediana de S é igual a (X2+X3)/2.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,46,$q$Estatística e Probabilidade$q$,$q$Nas condições do item anterior sobre a soma S = X1+X2+X3+X4 de uma amostra aleatória simples de tamanho n = 4 retirada de população normal: S segue uma distribuição binomial com parâmetro n = 4.$q$,$q$Nas condições do item anterior sobre a soma S = X1+X2+X3+X4 de uma amostra aleatória simples de tamanho n = 4 retirada de população normal: S segue uma distribuição binomial com parâmetro n = 4.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,47,$q$Estatística e Probabilidade$q$,$q$Nas condições dos itens anteriores sobre a soma S = X1+X2+X3+X4 de uma amostra aleatória simples de tamanho n = 4 retirada de população normal: A probabilidade de S = 4×μ é zero.$q$,$q$Nas condições dos itens anteriores sobre a soma S = X1+X2+X3+X4 de uma amostra aleatória simples de tamanho n = 4 retirada de população normal: A probabilidade de S = 4×μ é zero.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,48,$q$Estatística e Probabilidade$q$,$q$Nas condições dos itens anteriores sobre a soma S = X1+X2+X3+X4 de uma amostra aleatória simples de tamanho n = 4 retirada de população normal: O desvio padrão da razão S/√σ² é igual a 2.$q$,$q$Nas condições dos itens anteriores sobre a soma S = X1+X2+X3+X4 de uma amostra aleatória simples de tamanho n = 4 retirada de população normal: O desvio padrão da razão S/√σ² é igual a 2.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,49,$q$Estatística e Probabilidade$q$,$q$Em uma perícia sobre contratos licitatórios, foi analisada a diferença D entre os valores licitados (VL) e os valores efetivamente pagos (VP) para certo tipo de prestação de serviço. Selecionou-se uma amostra aleatória simples de 36 contratos, assumindo-se que a população seja descrita por uma distribuição normal. Os resultados mostram que, para a variável D = VL − VP, a média amostral foi R$ 5 mil e o desvio padrão amostral, R$ 3 mil. Além disso, a regressão linear simples da variável VP sobre VL, obtida pelo método de mínimos quadrados ordinários, foi VP = 0,5 + 1,1 × VL. Com base nesses dados: O coeficiente de correlação linear de Pearson entre as variáveis VL e VP foi igual a 1,1.$q$,$q$Em uma perícia sobre contratos licitatórios, foi analisada a diferença D entre os valores licitados (VL) e os valores efetivamente pagos (VP) para certo tipo de prestação de serviço. Selecionou-se uma amostra aleatória simples de 36 contratos, assumindo-se que a população seja descrita por uma distribuição normal. Os resultados mostram que, para a variável D = VL − VP, a média amostral foi R$ 5 mil e o desvio padrão amostral, R$ 3 mil. Além disso, a regressão linear simples da variável VP sobre VL, obtida pelo método de mínimos quadrados ordinários, foi VP = 0,5 + 1,1 × VL. Com base nesses dados: O coeficiente de correlação linear de Pearson entre as variáveis VL e VP foi igual a 1,1.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,50,$q$Estatística e Probabilidade$q$,$q$Nas condições do item anterior sobre a diferença D = VL − VP entre valores licitados e pagos (média amostral R$ 5 mil, desvio padrão amostral R$ 3 mil, amostra de 36 contratos): O intervalo de 95% de confiança para a diferença entre as médias populacionais dos valores licitados e dos valores efetivamente pagos foi R$ 5 mil ± R$ 0,5 mil.$q$,$q$Nas condições do item anterior sobre a diferença D = VL − VP entre valores licitados e pagos (média amostral R$ 5 mil, desvio padrão amostral R$ 3 mil, amostra de 36 contratos): O intervalo de 95% de confiança para a diferença entre as médias populacionais dos valores licitados e dos valores efetivamente pagos foi R$ 5 mil ± R$ 0,5 mil.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,51,$q$Estatística e Probabilidade$q$,$q$Nas condições dos itens anteriores sobre a diferença D = VL − VP entre valores licitados e pagos: O desvio padrão da variável VL foi superior ao desvio padrão da variável VP.$q$,$q$Nas condições dos itens anteriores sobre a diferença D = VL − VP entre valores licitados e pagos: O desvio padrão da variável VL foi superior ao desvio padrão da variável VP.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,52,$q$Estatística e Probabilidade$q$,$q$Nas condições dos itens anteriores sobre a diferença D = VL − VP entre valores licitados e pagos: A média amostral dos valores licitados (VL) foi de R$ 50 mil.$q$,$q$Nas condições dos itens anteriores sobre a diferença D = VL − VP entre valores licitados e pagos: A média amostral dos valores licitados (VL) foi de R$ 50 mil.$q$,'X',1,'annulled',false,true,$q$Item anulado no gabarito oficial definitivo (106_PF_CB2_01); não é exibido aos estudantes.$q$,'CB2'),
(2025,53,$q$Raciocínio Lógico-Matemático$q$,$q$Considere que, em uma tabela-verdade com proposições P, Q e R, → denote o condicional "se... então...", ∨ o conectivo "ou", e ~R a negação da proposição R, para a fórmula (P → Q) ∨ ~R. Com base nessas considerações, conclui-se que, ao preencher corretamente a última coluna da tabela-verdade, ocorrerão 4 valores V (verdade) e 4 valores F (falso).$q$,$q$Considere que, em uma tabela-verdade com proposições P, Q e R, → denote o condicional "se... então...", ∨ o conectivo "ou", e ~R a negação da proposição R, para a fórmula (P → Q) ∨ ~R. Com base nessas considerações, conclui-se que, ao preencher corretamente a última coluna da tabela-verdade, ocorrerão 4 valores V (verdade) e 4 valores F (falso).$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01. Enunciado reconstruído a partir da tabela-verdade impressa no caderno (colunas P, Q, R, P→Q∨~R).$q$,'CB2'),
(2025,54,$q$Raciocínio Lógico-Matemático$q$,$q$Considere que um crime foi cometido e três suspeitos desse crime, X, Y e Z, foram intimados e conduzidos a um interrogatório. Nessa ocasião, sobre o crime, X afirmou: "nem Y nem Z são culpados"; Z afirmou: "os culpados foram Y e X"; e Y afirmou: "o culpado foi Z ou X". Nessa situação, sabendo-se que todos os suspeitos mentiram, é correto concluir que o culpado do crime é X.$q$,$q$Considere que um crime foi cometido e três suspeitos desse crime, X, Y e Z, foram intimados e conduzidos a um interrogatório. Nessa ocasião, sobre o crime, X afirmou: "nem Y nem Z são culpados"; Z afirmou: "os culpados foram Y e X"; e Y afirmou: "o culpado foi Z ou X". Nessa situação, sabendo-se que todos os suspeitos mentiram, é correto concluir que o culpado do crime é X.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,55,$q$Raciocínio Lógico-Matemático$q$,$q$Considere que as seguintes proposições sejam verdadeiras. P: "Se Paulo é parente da vítima, então ele é inocente e estava no exterior no dia do crime". Q: "Se Paulo tem o mesmo sobrenome da vítima ou tem o mesmo tipo sanguíneo, então ele é parente da vítima". Com base nessas proposições, é correto afirmar que, se Paulo não estava no exterior no dia do crime, então ele não tem o mesmo tipo sanguíneo da vítima.$q$,$q$Considere que as seguintes proposições sejam verdadeiras. P: "Se Paulo é parente da vítima, então ele é inocente e estava no exterior no dia do crime". Q: "Se Paulo tem o mesmo sobrenome da vítima ou tem o mesmo tipo sanguíneo, então ele é parente da vítima". Com base nessas proposições, é correto afirmar que, se Paulo não estava no exterior no dia do crime, então ele não tem o mesmo tipo sanguíneo da vítima.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,56,$q$Raciocínio Lógico-Matemático$q$,$q$Suponha que a sentença "Se Aldo ou Bruno é filho de Carlos, então Daniel é pai de Elza e de Fernanda" seja verdadeira. Nesse caso, se Elza não for filha de Daniel, então Carlos não é pai de Aldo nem de Bruno.$q$,$q$Suponha que a sentença "Se Aldo ou Bruno é filho de Carlos, então Daniel é pai de Elza e de Fernanda" seja verdadeira. Nesse caso, se Elza não for filha de Daniel, então Carlos não é pai de Aldo nem de Bruno.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,57,$q$Raciocínio Lógico-Matemático$q$,$q$Em determinado dia, 1.000 veículos de carga, com seus respectivos condutores e cargas, passaram por um posto de fiscalização de fronteira. Desses, 800 estavam com a documentação em situação regular — o veículo, o condutor e a carga —, e 200 apresentavam alguma irregularidade na documentação — do veículo, do condutor ou da carga. Além disso, as placas de todos esses 1.000 veículos foram devidamente registradas. Tendo como base essa situação: A negação da sentença "todo condutor abordado na fiscalização era brasileiro ou estrangeiro" é a seguinte sentença: "nenhum condutor abordado na fiscalização era brasileiro ou estrangeiro".$q$,$q$Em determinado dia, 1.000 veículos de carga, com seus respectivos condutores e cargas, passaram por um posto de fiscalização de fronteira. Desses, 800 estavam com a documentação em situação regular — o veículo, o condutor e a carga —, e 200 apresentavam alguma irregularidade na documentação — do veículo, do condutor ou da carga. Além disso, as placas de todos esses 1.000 veículos foram devidamente registradas. Tendo como base essa situação: A negação da sentença "todo condutor abordado na fiscalização era brasileiro ou estrangeiro" é a seguinte sentença: "nenhum condutor abordado na fiscalização era brasileiro ou estrangeiro".$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,58,$q$Raciocínio Lógico-Matemático$q$,$q$Nas condições do item anterior sobre os 1.000 veículos de carga fiscalizados (800 regulares e 200 irregulares): Se duas placas forem aleatoriamente selecionadas ao final do dia entre as 1.000 placas registradas, será superior a 0,3 a probabilidade de uma delas pertencer a um veículo/condutor/carga em situação irregular e a outra, a um veículo/condutor/carga em situação regular.$q$,$q$Nas condições do item anterior sobre os 1.000 veículos de carga fiscalizados (800 regulares e 200 irregulares): Se duas placas forem aleatoriamente selecionadas ao final do dia entre as 1.000 placas registradas, será superior a 0,3 a probabilidade de uma delas pertencer a um veículo/condutor/carga em situação irregular e a outra, a um veículo/condutor/carga em situação regular.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,59,$q$Raciocínio Lógico-Matemático$q$,$q$Nas condições dos itens anteriores sobre os 1.000 veículos de carga fiscalizados: Considere que as placas de todos os veículos sejam constituídas por uma sequência de 4 letras justaposta a uma sequência de 3 dígitos numéricos entre 0 e 9, admitindo-se repetições. Considere, ainda, que a soma dos dígitos numéricos da placa de cada um dos 1.000 veículos fiscalizados seja sempre superior ou igual a 26. Nessa situação, pelo menos 250 placas têm os mesmos dígitos numéricos, nas mesmas posições.$q$,$q$Nas condições dos itens anteriores sobre os 1.000 veículos de carga fiscalizados: Considere que as placas de todos os veículos sejam constituídas por uma sequência de 4 letras justaposta a uma sequência de 3 dígitos numéricos entre 0 e 9, admitindo-se repetições. Considere, ainda, que a soma dos dígitos numéricos da placa de cada um dos 1.000 veículos fiscalizados seja sempre superior ou igual a 26. Nessa situação, pelo menos 250 placas têm os mesmos dígitos numéricos, nas mesmas posições.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,60,$q$Raciocínio Lógico-Matemático$q$,$q$Considere que, entre os veículos em situação irregular do posto de fiscalização de fronteira: 120 apresentavam problemas na documentação do veículo; 85, na documentação do condutor; e 40, na documentação da carga transportada. Além disso, os veículos com problemas na documentação da carga não apresentavam problemas na documentação do veículo nem na documentação do condutor. Nessa situação, é inferior a 40 a quantidade de veículos que apresentavam, simultaneamente, irregularidades na documentação do veículo e do seu condutor.$q$,$q$Considere que, entre os veículos em situação irregular do posto de fiscalização de fronteira: 120 apresentavam problemas na documentação do veículo; 85, na documentação do condutor; e 40, na documentação da carga transportada. Além disso, os veículos com problemas na documentação da carga não apresentavam problemas na documentação do veículo nem na documentação do condutor. Nessa situação, é inferior a 40 a quantidade de veículos que apresentavam, simultaneamente, irregularidades na documentação do veículo e do seu condutor.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CB2 (Conhecimentos Básicos Bloco I) da PF 2025; gabarito conferido em 106_PF_CB2_01.$q$,'CB2'),
(2025,61,$q$Informática$q$,$q$O Microsoft Remote Desktop e o TeamViewer permitem acesso remoto a computadores, o que possibilita a transferência de arquivos, e os ambientes Microsoft Office e LibreOffice oferecem ferramentas para criação de textos, planilhas e apresentações, garantindo compatibilidade com diversos formatos.$q$,$q$O Microsoft Remote Desktop e o TeamViewer permitem acesso remoto a computadores, o que possibilita a transferência de arquivos, e os ambientes Microsoft Office e LibreOffice oferecem ferramentas para criação de textos, planilhas e apresentações, garantindo compatibilidade com diversos formatos.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,62,$q$Informática$q$,$q$A Internet é uma rede pública global de comunicação e acesso a informações, ao passo que a intranet é restrita a organizações; ambas permitem o uso de navegadores, email, grupos de discussão, mecanismos de busca e redes sociais, e utilizam tecnologias como autenticação e criptografia, que garantem segurança no compartilhamento de dados.$q$,$q$A Internet é uma rede pública global de comunicação e acesso a informações, ao passo que a intranet é restrita a organizações; ambas permitem o uso de navegadores, email, grupos de discussão, mecanismos de busca e redes sociais, e utilizam tecnologias como autenticação e criptografia, que garantem segurança no compartilhamento de dados.$q$,'X',1,'annulled',false,true,$q$Item anulado no gabarito oficial definitivo (106_PF_CG1_01); não é exibido aos estudantes.$q$,'CG1'),
(2025,63,$q$Informática$q$,$q$Em distribuições Linux, o comando ipconfig é utilizado para exibir informações de configuração de rede, como endereço IP e máscara de sub-rede; no Windows, o comando ifconfig desempenha a mesma função, permitindo a visualização e configuração de interfaces de rede.$q$,$q$Em distribuições Linux, o comando ipconfig é utilizado para exibir informações de configuração de rede, como endereço IP e máscara de sub-rede; no Windows, o comando ifconfig desempenha a mesma função, permitindo a visualização e configuração de interfaces de rede.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,64,$q$Informática$q$,$q$Firewalls são ferramentas de segurança que monitoram e controlam o tráfego de dados entre redes, podendo bloquear acessos não autorizados, ao passo que os antivírus são projetados para detectar, remover e prevenir a ação de vírus e outras pragas virtuais.$q$,$q$Firewalls são ferramentas de segurança que monitoram e controlam o tráfego de dados entre redes, podendo bloquear acessos não autorizados, ao passo que os antivírus são projetados para detectar, remover e prevenir a ação de vírus e outras pragas virtuais.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,65,$q$Informática$q$,$q$No protocolo IPv6, cada endereço tem 256 bits, que são divididos em duas partes (a primeira define a rede e a segunda identifica o host); esse protocolo elimina o uso de máscaras de sub-rede, substituindo-as por prefixos de rede fixos; por sua vez, o IPv4 utiliza endereços de 32 bits e máscaras de sub-rede variáveis para definir a separação entre rede e host.$q$,$q$No protocolo IPv6, cada endereço tem 256 bits, que são divididos em duas partes (a primeira define a rede e a segunda identifica o host); esse protocolo elimina o uso de máscaras de sub-rede, substituindo-as por prefixos de rede fixos; por sua vez, o IPv4 utiliza endereços de 32 bits e máscaras de sub-rede variáveis para definir a separação entre rede e host.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,66,$q$Informática$q$,$q$Na arquitetura de sistemas, o frontend é a interface visível e interativa com o usuário, enquanto o backend realiza o processamento de dados e a lógica de negócios; essa separação reflete os princípios da teoria geral de sistemas, segundo a qual a organização de sistemas em partes interdependentes facilita sua compreensão e manutenção.$q$,$q$Na arquitetura de sistemas, o frontend é a interface visível e interativa com o usuário, enquanto o backend realiza o processamento de dados e a lógica de negócios; essa separação reflete os princípios da teoria geral de sistemas, segundo a qual a organização de sistemas em partes interdependentes facilita sua compreensão e manutenção.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,67,$q$Informática$q$,$q$A computação em nuvem permite que os usuários acessem recursos computacionais sob demanda, como armazenamento e processamento, sem a necessidade de conexão com a Internet, pois os dados e serviços são armazenados localmente nos dispositivos dos usuários.$q$,$q$A computação em nuvem permite que os usuários acessem recursos computacionais sob demanda, como armazenamento e processamento, sem a necessidade de conexão com a Internet, pois os dados e serviços são armazenados localmente nos dispositivos dos usuários.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,68,$q$Informática$q$,$q$Na análise de requisitos de um sistema de informação, a etapa de especificação pode ser desconsiderada e substituída diretamente pelos ambientes de testes, homologação e produção, desde que os requisitos tenham sido bem definidos e documentados.$q$,$q$Na análise de requisitos de um sistema de informação, a etapa de especificação pode ser desconsiderada e substituída diretamente pelos ambientes de testes, homologação e produção, desde que os requisitos tenham sido bem definidos e documentados.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,69,$q$Informática$q$,$q$No modelo entidade-relacionamento, a abstração representa o mundo real com entidades, atributos e relacionamentos binários, ternários ou superiores; no modelo relacional, a integridade referencial depende de chaves primárias e estrangeiras, enquanto a análise funcional identifica dependências e normaliza tabelas até a forma normal adequada (3FN, Boyce-Codd ou 4FN), eliminando redundâncias e anomalias.$q$,$q$No modelo entidade-relacionamento, a abstração representa o mundo real com entidades, atributos e relacionamentos binários, ternários ou superiores; no modelo relacional, a integridade referencial depende de chaves primárias e estrangeiras, enquanto a análise funcional identifica dependências e normaliza tabelas até a forma normal adequada (3FN, Boyce-Codd ou 4FN), eliminando redundâncias e anomalias.$q$,'X',1,'annulled',false,true,$q$Item anulado no gabarito oficial definitivo (106_PF_CG1_01); não é exibido aos estudantes.$q$,'CG1'),
(2025,70,$q$Informática$q$,$q$A mineração de dados é uma técnica em que se utilizam exclusivamente algoritmos de aprendizado supervisionado para a identificação de padrões em grandes volumes de dados; no contexto de Big Data, a premissa principal é a utilização de bancos de dados relacionais tradicionais, que são suficientes para o enfrentamento dos desafios de volume, variedade e velocidade característicos desse ambiente.$q$,$q$A mineração de dados é uma técnica em que se utilizam exclusivamente algoritmos de aprendizado supervisionado para a identificação de padrões em grandes volumes de dados; no contexto de Big Data, a premissa principal é a utilização de bancos de dados relacionais tradicionais, que são suficientes para o enfrentamento dos desafios de volume, variedade e velocidade característicos desse ambiente.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,71,$q$Informática$q$,$q$No contexto de banco de dados, dados estruturados são aqueles que não possuem um formato fixo e são armazenados em sistemas como bancos NoSQL, ao passo que dados não estruturados possuem um formato rígido e são armazenados em tabelas relacionais.$q$,$q$No contexto de banco de dados, dados estruturados são aqueles que não possuem um formato fixo e são armazenados em sistemas como bancos NoSQL, ao passo que dados não estruturados possuem um formato rígido e são armazenados em tabelas relacionais.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,72,$q$Informática$q$,$q$Na teoria da informação, dados representam fatos brutos que, quando organizados e interpretados, se transformam em informação, e a segurança da informação busca protegê-los contra acessos não autorizados, garantindo sua confidencialidade, integridade e disponibilidade.$q$,$q$Na teoria da informação, dados representam fatos brutos que, quando organizados e interpretados, se transformam em informação, e a segurança da informação busca protegê-los contra acessos não autorizados, garantindo sua confidencialidade, integridade e disponibilidade.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,73,$q$Informática$q$,$q$Em sistemas biométricos de alta segurança, o controle do FNIR é mais relevante que o do FPIR, pois rejeitar um usuário legítimo acarreta maior risco que aceitar um impostor.$q$,$q$Em sistemas biométricos de alta segurança, o controle do FNIR é mais relevante que o do FPIR, pois rejeitar um usuário legítimo acarreta maior risco que aceitar um impostor.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,74,$q$Informática$q$,$q$O indicador FPIR é diretamente influenciado por um limiar de decisão mal ajustado, o que pode comprometer a segurança de sistemas biométricos ao se aceitarem usuários não autorizados.$q$,$q$O indicador FPIR é diretamente influenciado por um limiar de decisão mal ajustado, o que pode comprometer a segurança de sistemas biométricos ao se aceitarem usuários não autorizados.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,75,$q$Informática$q$,$q$Em Python, a função lambda permite a criação de funções anônimas, que podem ser usadas como argumentos em funções de ordem superior, o que facilita a programação funcional.$q$,$q$Em Python, a função lambda permite a criação de funções anônimas, que podem ser usadas como argumentos em funções de ordem superior, o que facilita a programação funcional.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,76,$q$Informática$q$,$q$No modo de transmissão full-duplex, para que os dados sejam transmitidos simultaneamente em ambos os sentidos, os dispositivos devem estar sincronizados no mesmo clock lógico de rede.$q$,$q$No modo de transmissão full-duplex, para que os dados sejam transmitidos simultaneamente em ambos os sentidos, os dispositivos devem estar sincronizados no mesmo clock lógico de rede.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,77,$q$Informática$q$,$q$A camada de sessão do modelo OSI é a principal responsável pela fragmentação e reconstrução de pacotes IP entre sistemas finais na rede.$q$,$q$A camada de sessão do modelo OSI é a principal responsável pela fragmentação e reconstrução de pacotes IP entre sistemas finais na rede.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,78,$q$Informática$q$,$q$Em Python, listas são estruturas de dados imutáveis, o que as torna ideais para serem usadas como chaves de dicionários (dict).$q$,$q$Em Python, listas são estruturas de dados imutáveis, o que as torna ideais para serem usadas como chaves de dicionários (dict).$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,79,$q$Informática$q$,$q$Em serviços de nuvem, a utilização de plataforma como serviço (PaaS) é mais recomendada para empresas que desejem controlar totalmente o hardware e o sistema operacional utilizados.$q$,$q$Em serviços de nuvem, a utilização de plataforma como serviço (PaaS) é mais recomendada para empresas que desejem controlar totalmente o hardware e o sistema operacional utilizados.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,80,$q$Informática$q$,$q$Em machine learning supervisionado, o algoritmo aprende, a partir de um conjunto de dados rotulados, a identificar padrões e realizar previsões em novos dados.$q$,$q$Em machine learning supervisionado, o algoritmo aprende, a partir de um conjunto de dados rotulados, a identificar padrões e realizar previsões em novos dados.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,81,$q$Informática$q$,$q$No ambiente Linux, a execução do comando "chmod 755 policial.pdf" atribuirá permissões de leitura, escrita e execução para o proprietário do arquivo policial.pdf, e atribuirá permissões de leitura e execução para grupo e outros usuários.$q$,$q$No ambiente Linux, a execução do comando "chmod 755 policial.pdf" atribuirá permissões de leitura, escrita e execução para o proprietário do arquivo policial.pdf, e atribuirá permissões de leitura e execução para grupo e outros usuários.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,82,$q$Informática$q$,$q$A infraestrutura como serviço (IaaS) oferece aos usuários recursos computacionais virtuais como servidores, armazenamento e redes, mas o gerenciamento do sistema operacional fica sob responsabilidade do cliente.$q$,$q$A infraestrutura como serviço (IaaS) oferece aos usuários recursos computacionais virtuais como servidores, armazenamento e redes, mas o gerenciamento do sistema operacional fica sob responsabilidade do cliente.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,83,$q$Informática$q$,$q$O DNS é responsável por garantir a confidencialidade das comunicações entre cliente e servidor por meio de criptografia ponta a ponta embutida no próprio protocolo desde a sua concepção.$q$,$q$O DNS é responsável por garantir a confidencialidade das comunicações entre cliente e servidor por meio de criptografia ponta a ponta embutida no próprio protocolo desde a sua concepção.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,84,$q$Informática$q$,$q$O DNS utiliza o protocolo UDP para a maioria das consultas, mas pode usar o TCP para transferência de zonas e consultas que excedam 512 bytes.$q$,$q$O DNS utiliza o protocolo UDP para a maioria das consultas, mas pode usar o TCP para transferência de zonas e consultas que excedam 512 bytes.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,85,$q$Informática$q$,$q$O protocolo HMAC-based one-time password (HOTP) é uma solução usada em autenticação multifator (MFA) para a geração de códigos de autenticação que não expiram.$q$,$q$O protocolo HMAC-based one-time password (HOTP) é uma solução usada em autenticação multifator (MFA) para a geração de códigos de autenticação que não expiram.$q$,'X',1,'annulled',false,true,$q$Item anulado no gabarito oficial definitivo (106_PF_CG1_01); não é exibido aos estudantes.$q$,'CG1'),
(2025,86,$q$Informática$q$,$q$Em autenticação multifator (MFA), hardwares tokens equivalem a dispositivos físicos que geram códigos de autenticação ou permitem autenticação via porta USB em computadores com esse tipo de interface.$q$,$q$Em autenticação multifator (MFA), hardwares tokens equivalem a dispositivos físicos que geram códigos de autenticação ou permitem autenticação via porta USB em computadores com esse tipo de interface.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,87,$q$Informática$q$,$q$A técnica sandboxing, ao executar programas em um ambiente compartilhado para observar seu comportamento, altera o sistema principal.$q$,$q$A técnica sandboxing, ao executar programas em um ambiente compartilhado para observar seu comportamento, altera o sistema principal.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,88,$q$Informática$q$,$q$Detecção heurística é uma técnica de análise do comportamento e da estrutura do código para a identificação de características típicas de vírus, ainda que a assinatura específica não seja conhecida.$q$,$q$Detecção heurística é uma técnica de análise do comportamento e da estrutura do código para a identificação de características típicas de vírus, ainda que a assinatura específica não seja conhecida.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,89,$q$Informática$q$,$q$Por princípio, a consistência pressupõe que uma transação inconsistente deve levar o banco de dados de um estado inconsistente para o estado consistente.$q$,$q$Por princípio, a consistência pressupõe que uma transação inconsistente deve levar o banco de dados de um estado inconsistente para o estado consistente.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,90,$q$Informática$q$,$q$Para a garantia dos princípios de atomicidade em banco de dados, uma transação somente é confirmada e tornada permanente no banco de dados após todas as suas operações serem executadas com sucesso.$q$,$q$Para a garantia dos princípios de atomicidade em banco de dados, uma transação somente é confirmada e tornada permanente no banco de dados após todas as suas operações serem executadas com sucesso.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,91,$q$Informática$q$,$q$Considere o seguinte código SQL: CREATE TABLE catalogo (id_tabela INT, nome_tabela VARCHAR(255), descricao TEXT, colunas TEXT, relacionamentos TEXT, regras_negocio TEXT, data_criacao DATE, data_ultima_atualizacao DATE); INSERT INTO catalogo VALUES (1, 'vendas', 'Registros de vendas realizadas', 'id_venda INT, data_venda DATE, valor_venda DECIMAL, id_produto INT', 'id_produto REFERENCES produtos(id)', 'valor_venda > 0', '2023-01-01', '2023-10-05'); SELECT * FROM catalogo WHERE nome_tabela = 'vendas'; Com base nas informações do código precedente: O comando SELECT mostra que existe uma relação com uma tabela de nome produtos mediante id_produto.$q$,$q$Considere o seguinte código SQL: CREATE TABLE catalogo (id_tabela INT, nome_tabela VARCHAR(255), descricao TEXT, colunas TEXT, relacionamentos TEXT, regras_negocio TEXT, data_criacao DATE, data_ultima_atualizacao DATE); INSERT INTO catalogo VALUES (1, 'vendas', 'Registros de vendas realizadas', 'id_venda INT, data_venda DATE, valor_venda DECIMAL, id_produto INT', 'id_produto REFERENCES produtos(id)', 'valor_venda > 0', '2023-01-01', '2023-10-05'); SELECT * FROM catalogo WHERE nome_tabela = 'vendas'; Com base nas informações do código precedente: O comando SELECT mostra que existe uma relação com uma tabela de nome produtos mediante id_produto.$q$,'X',1,'annulled',false,true,$q$Item anulado no gabarito oficial definitivo (106_PF_CG1_01); não é exibido aos estudantes.$q$,'CG1'),
(2025,92,$q$Informática$q$,$q$Nas condições do item anterior, com base no mesmo código SQL da tabela catalogo: Pelo comando SELECT, entende-se que os valores da coluna valor_venda devem ser menores que zero.$q$,$q$Nas condições do item anterior, com base no mesmo código SQL da tabela catalogo: Pelo comando SELECT, entende-se que os valores da coluna valor_venda devem ser menores que zero.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,93,$q$Informática$q$,$q$Em aprendizado de máquina, as técnicas de classificação e regressão são exemplos de aplicações práticas para a solução de problemas.$q$,$q$Em aprendizado de máquina, as técnicas de classificação e regressão são exemplos de aplicações práticas para a solução de problemas.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,94,$q$Informática$q$,$q$REST (Representational state transfer) e GraphQL são dois tipos de API, cada um com suas características técnicas particulares.$q$,$q$REST (Representational state transfer) e GraphQL são dois tipos de API, cada um com suas características técnicas particulares.$q$,'X',1,'annulled',false,true,$q$Item anulado no gabarito oficial definitivo (106_PF_CG1_01); não é exibido aos estudantes.$q$,'CG1'),
(2025,95,$q$Informática$q$,$q$Em aprendizado de máquina, não há overfitting.$q$,$q$Em aprendizado de máquina, não há overfitting.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,96,$q$Informática$q$,$q$Uma API deve manter estado entre as requisições visto que, para cada requisição, é necessária a completude oriunda de outra requisição a fim de que a aplicação tenha todas as informações necessárias para processá-la.$q$,$q$Uma API deve manter estado entre as requisições visto que, para cada requisição, é necessária a completude oriunda de outra requisição a fim de que a aplicação tenha todas as informações necessárias para processá-la.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno CG1 (Conhecimentos Básicos Bloco II - Informática) da PF 2025; gabarito conferido em 106_PF_CG1_01.$q$,'CG1'),
(2025,97,$q$Contabilidade Geral$q$,$q$Uma empresa que realiza a compra de um terreno no valor de R$ 120.000 à vista, com recursos bancários, deve lançar esse valor a débito na conta bancos e a crédito na conta terrenos, pois está saindo dinheiro e entrando um bem.$q$,$q$Uma empresa que realiza a compra de um terreno no valor de R$ 120.000 à vista, com recursos bancários, deve lançar esse valor a débito na conta bancos e a crédito na conta terrenos, pois está saindo dinheiro e entrando um bem.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16).$q$,'específica'),
(2025,98,$q$Contabilidade Geral$q$,$q$O plano de contas é um dos livros contábeis obrigatórios das empresas, devendo ser registrado e autenticado na junta comercial juntamente com o livro diário e o livro-razão.$q$,$q$O plano de contas é um dos livros contábeis obrigatórios das empresas, devendo ser registrado e autenticado na junta comercial juntamente com o livro diário e o livro-razão.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16).$q$,'específica'),
(2025,99,$q$Contabilidade Geral$q$,$q$A principal finalidade do relatório financeiro para fins gerais é atender às necessidades da administração da entidade, fornecendo informações internas detalhadas para o planejamento e controle operacional e priorizando os usuários internos em detrimento dos externos.$q$,$q$A principal finalidade do relatório financeiro para fins gerais é atender às necessidades da administração da entidade, fornecendo informações internas detalhadas para o planejamento e controle operacional e priorizando os usuários internos em detrimento dos externos.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16).$q$,'específica'),
(2025,100,$q$Contabilidade Geral$q$,$q$Uma movimentação entre contas do ativo e do passivo é classificada como fato modificativo, uma vez que envolve variação na estrutura patrimonial da entidade e altera diretamente o valor do patrimônio.$q$,$q$Uma movimentação entre contas do ativo e do passivo é classificada como fato modificativo, uma vez que envolve variação na estrutura patrimonial da entidade e altera diretamente o valor do patrimônio.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16).$q$,'específica'),
(2025,101,$q$Contabilidade Geral$q$,$q$O valor do patrimônio líquido de uma entidade no início de determinado ano resulta da diferença entre o total de bens e direitos da entidade e o montante de suas obrigações.$q$,$q$O valor do patrimônio líquido de uma entidade no início de determinado ano resulta da diferença entre o total de bens e direitos da entidade e o montante de suas obrigações.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16).$q$,'específica'),
(2025,102,$q$Contabilidade Geral$q$,$q$Os fatos administrativos permutativos correspondem à troca entre elementos do ativo ou do passivo que não alteram o patrimônio líquido, tal como ocorre na aquisição de um item para venda com pagamento à vista, que reduz o ativo caixa e aumenta o ativo estoque; entretanto, uma troca que envolva aumento simultâneo do ativo e do passivo não caracteriza fato permutativo, pois altera o patrimônio da empresa.$q$,$q$Os fatos administrativos permutativos correspondem à troca entre elementos do ativo ou do passivo que não alteram o patrimônio líquido, tal como ocorre na aquisição de um item para venda com pagamento à vista, que reduz o ativo caixa e aumenta o ativo estoque; entretanto, uma troca que envolva aumento simultâneo do ativo e do passivo não caracteriza fato permutativo, pois altera o patrimônio da empresa.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16).$q$,'específica'),
(2025,103,$q$Contabilidade Geral$q$,$q$Considere que, em determinado período, uma empresa tenha vendido R$ 125.000 e só recebido R$ 115.000 (o restante receberá no futuro); considere, ainda, que a mesma empresa tenha tido, no mesmo período, despesa de R$ 110.000 e tenha pago R$ 108.000. Com base nesses dados, conclui-se que, pelo regime de competência, a empresa apresentou lucro de R$ 15.000 no período.$q$,$q$Considere que, em determinado período, uma empresa tenha vendido R$ 125.000 e só recebido R$ 115.000 (o restante receberá no futuro); considere, ainda, que a mesma empresa tenha tido, no mesmo período, despesa de R$ 110.000 e tenha pago R$ 108.000. Com base nesses dados, conclui-se que, pelo regime de competência, a empresa apresentou lucro de R$ 15.000 no período.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16).$q$,'específica'),
(2025,104,$q$Contabilidade Geral$q$,$q$O livro diário deve conter, para cada lançamento, a data do fato, a conta debitada, a conta creditada, o histórico da operação e o valor correspondente, e nele deve-se obedecer à ordem cronológica dos registros.$q$,$q$O livro diário deve conter, para cada lançamento, a data do fato, a conta debitada, a conta creditada, o histórico da operação e o valor correspondente, e nele deve-se obedecer à ordem cronológica dos registros.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16).$q$,'específica'),
(2025,105,$q$Contabilidade Geral$q$,$q$Pelo regime de competência, as receitas de vendas devem ser contabilizadas somente no momento do recebimento do dinheiro, independentemente da entrega do produto ou serviço.$q$,$q$Pelo regime de competência, as receitas de vendas devem ser contabilizadas somente no momento do recebimento do dinheiro, independentemente da entrega do produto ou serviço.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16).$q$,'específica'),
(2025,106,$q$Contabilidade Geral$q$,$q$O valor pago antecipadamente pelo aluguel de uma sala comercial para uso por período de seis meses deve ser registrado pela empresa locatária como um direito no ativo, na conta despesas antecipadas, e deverá ser apropriado mensalmente como despesa, à medida que o direito de uso da sala for sendo consumido.$q$,$q$O valor pago antecipadamente pelo aluguel de uma sala comercial para uso por período de seis meses deve ser registrado pela empresa locatária como um direito no ativo, na conta despesas antecipadas, e deverá ser apropriado mensalmente como despesa, à medida que o direito de uso da sala for sendo consumido.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16).$q$,'específica'),
(2025,107,$q$Contabilidade Geral$q$,$q$Com base nos seguintes saldos contábeis extraídos do balancete de uma empresa em 31/12 de determinado ano — bancos R$ 95.000; materiais de consumo R$ 4.000; máquinas R$ 9.000; contas a pagar R$ 5.700; capital R$ 100.000; receita de serviços R$ 7.000; despesas com taxas R$ 1.500; despesa com pró-labore R$ 2.000; despesa antecipada R$ 1.200: O patrimônio líquido total da entidade, considerado o resultado do exercício, é de R$ 100.000.$q$,$q$Com base nos seguintes saldos contábeis extraídos do balancete de uma empresa em 31/12 de determinado ano — bancos R$ 95.000; materiais de consumo R$ 4.000; máquinas R$ 9.000; contas a pagar R$ 5.700; capital R$ 100.000; receita de serviços R$ 7.000; despesas com taxas R$ 1.500; despesa com pró-labore R$ 2.000; despesa antecipada R$ 1.200: O patrimônio líquido total da entidade, considerado o resultado do exercício, é de R$ 100.000.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16).$q$,'específica'),
(2025,108,$q$Contabilidade Geral$q$,$q$Nas condições do item anterior, com base no mesmo balancete de 31/12 (bancos R$ 95.000; materiais de consumo R$ 4.000; máquinas R$ 9.000; contas a pagar R$ 5.700; capital R$ 100.000; receita de serviços R$ 7.000; despesas com taxas R$ 1.500; despesa com pró-labore R$ 2.000; despesa antecipada R$ 1.200): O passivo circulante resulta no valor de R$ 5.700.$q$,$q$Nas condições do item anterior, com base no mesmo balancete de 31/12 (bancos R$ 95.000; materiais de consumo R$ 4.000; máquinas R$ 9.000; contas a pagar R$ 5.700; capital R$ 100.000; receita de serviços R$ 7.000; despesas com taxas R$ 1.500; despesa com pró-labore R$ 2.000; despesa antecipada R$ 1.200): O passivo circulante resulta no valor de R$ 5.700.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16).$q$,'específica'),
(2025,109,$q$Contabilidade Geral$q$,$q$Nas condições dos itens anteriores, com base no mesmo balancete de 31/12 (bancos R$ 95.000; materiais de consumo R$ 4.000; máquinas R$ 9.000; contas a pagar R$ 5.700; capital R$ 100.000; receita de serviços R$ 7.000; despesas com taxas R$ 1.500; despesa com pró-labore R$ 2.000; despesa antecipada R$ 1.200): O ativo soma R$ 109.200.$q$,$q$Nas condições dos itens anteriores, com base no mesmo balancete de 31/12 (bancos R$ 95.000; materiais de consumo R$ 4.000; máquinas R$ 9.000; contas a pagar R$ 5.700; capital R$ 100.000; receita de serviços R$ 7.000; despesas com taxas R$ 1.500; despesa com pró-labore R$ 2.000; despesa antecipada R$ 1.200): O ativo soma R$ 109.200.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16).$q$,'específica'),
(2025,110,$q$Contabilidade Geral$q$,$q$Nas condições dos itens anteriores, com base no mesmo balancete de 31/12 (bancos R$ 95.000; materiais de consumo R$ 4.000; máquinas R$ 9.000; contas a pagar R$ 5.700; capital R$ 100.000; receita de serviços R$ 7.000; despesas com taxas R$ 1.500; despesa com pró-labore R$ 2.000; despesa antecipada R$ 1.200): O lucro apurado no exercício é de R$ 3.500.$q$,$q$Nas condições dos itens anteriores, com base no mesmo balancete de 31/12 (bancos R$ 95.000; materiais de consumo R$ 4.000; máquinas R$ 9.000; contas a pagar R$ 5.700; capital R$ 100.000; receita de serviços R$ 7.000; despesas com taxas R$ 1.500; despesa com pró-labore R$ 2.000; despesa antecipada R$ 1.200): O lucro apurado no exercício é de R$ 3.500.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16).$q$,'específica'),
(2025,111,$q$Contabilidade Geral$q$,$q$O balancete de verificação permite que se identifiquem lançamentos que, embora estejam com débito e crédito equilibrados, tenham sido registrados equivocadamente em contas indevidas.$q$,$q$O balancete de verificação permite que se identifiquem lançamentos que, embora estejam com débito e crédito equilibrados, tenham sido registrados equivocadamente em contas indevidas.$q$,'X',1,'annulled',false,true,$q$Item anulado no gabarito oficial definitivo (106_PF_016_01, CARGO 16); não é exibido aos estudantes.$q$,'específica'),
(2025,112,$q$Contabilidade Geral$q$,$q$De acordo com o Pronunciamento n.º 26 (R1) do Comitê de Pronunciamentos Contábeis (CPC), os impostos diferidos devem ser classificados no balanço patrimonial como ativo ou passivo não circulante.$q$,$q$De acordo com o Pronunciamento n.º 26 (R1) do Comitê de Pronunciamentos Contábeis (CPC), os impostos diferidos devem ser classificados no balanço patrimonial como ativo ou passivo não circulante.$q$,'X',1,'annulled',true,false,$q$Item anulado no gabarito oficial definitivo (106_PF_016_01, CARGO 16); não é exibido aos estudantes.$q$,'específica'),
(2025,113,$q$Contabilidade Geral$q$,$q$Na demonstração de resultados do exercício, a receita líquida corresponde à receita bruta menos as deduções, tais como devoluções de venda, impostos sobre vendas e descontos comerciais.$q$,$q$Na demonstração de resultados do exercício, a receita líquida corresponde à receita bruta menos as deduções, tais como devoluções de venda, impostos sobre vendas e descontos comerciais.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16).$q$,'específica'),
(2025,114,$q$Contabilidade Geral$q$,$q$Um ativo temporariamente retirado de uso deve continuar sendo depreciado, exceto se já estiver totalmente depreciado ou se o método de depreciação adotado estiver diretamente vinculado ao seu uso.$q$,$q$Um ativo temporariamente retirado de uso deve continuar sendo depreciado, exceto se já estiver totalmente depreciado ou se o método de depreciação adotado estiver diretamente vinculado ao seu uso.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16). Base normativa (CPC 27) ainda não conferida individualmente na fonte oficial — aguardando revisão item a item antes de content_status=active.$q$,'específica'),
(2025,115,$q$Contabilidade Geral$q$,$q$A provisão para contingência deve ser reconhecida no passivo sempre que a perda for considerada possível, independentemente do trânsito em julgado da ação judicial que a motivou.$q$,$q$A provisão para contingência deve ser reconhecida no passivo sempre que a perda for considerada possível, independentemente do trânsito em julgado da ação judicial que a motivou.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16). Base normativa (CPC 25) ainda não conferida individualmente na fonte oficial — aguardando revisão item a item antes de content_status=active.$q$,'específica'),
(2025,116,$q$Contabilidade Geral$q$,$q$A provisão para férias representa um passivo para a empresa e deve ser reconhecida como despesa por ocasião do gozo de férias pelo empregado.$q$,$q$A provisão para férias representa um passivo para a empresa e deve ser reconhecida como despesa por ocasião do gozo de férias pelo empregado.$q$,'E',1,'under_review',false,true,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16).$q$,'específica'),
(2025,117,$q$Contabilidade Geral$q$,$q$De acordo com o Pronunciamento n.º 27 do CPC, a depreciação de um ativo deve cessar quando o bem estiver totalmente depreciado ou quando este for classificado como disponível para venda.$q$,$q$De acordo com o Pronunciamento n.º 27 do CPC, a depreciação de um ativo deve cessar quando o bem estiver totalmente depreciado ou quando este for classificado como disponível para venda.$q$,'X',1,'annulled',true,false,$q$Item anulado no gabarito oficial definitivo (106_PF_016_01, CARGO 16); não é exibido aos estudantes.$q$,'específica'),
(2025,118,$q$Contabilidade Geral$q$,$q$Com base na Estrutura Conceitual para Elaboração e Divulgação de Relatório Contábil-financeiro – CPC 00 (R2): A relevância e a compreensibilidade são as características fundamentais da informação contábil.$q$,$q$Com base na Estrutura Conceitual para Elaboração e Divulgação de Relatório Contábil-financeiro – CPC 00 (R2): A relevância e a compreensibilidade são as características fundamentais da informação contábil.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16). Base normativa (CPC 00 R2) ainda não conferida individualmente na fonte oficial — aguardando revisão item a item antes de content_status=active.$q$,'específica'),
(2025,119,$q$Contabilidade Geral$q$,$q$Nas condições do item anterior, com base na Estrutura Conceitual para Elaboração e Divulgação de Relatório Contábil-financeiro – CPC 00 (R2): A relevância da informação contábil está associada à sua capacidade de influenciar as decisões econômicas de seus usuários.$q$,$q$Nas condições do item anterior, com base na Estrutura Conceitual para Elaboração e Divulgação de Relatório Contábil-financeiro – CPC 00 (R2): A relevância da informação contábil está associada à sua capacidade de influenciar as decisões econômicas de seus usuários.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16). Base normativa (CPC 00 R2) ainda não conferida individualmente na fonte oficial — aguardando revisão item a item antes de content_status=active.$q$,'específica'),
(2025,120,$q$Contabilidade Geral$q$,$q$Nas condições dos itens anteriores, com base na Estrutura Conceitual para Elaboração e Divulgação de Relatório Contábil-financeiro – CPC 00 (R2): O custo corrente de um ativo corresponde ao valor presente dos fluxos de caixa futuros que a entidade espera obter a partir do uso contínuo do ativo.$q$,$q$Nas condições dos itens anteriores, com base na Estrutura Conceitual para Elaboração e Divulgação de Relatório Contábil-financeiro – CPC 00 (R2): O custo corrente de um ativo corresponde ao valor presente dos fluxos de caixa futuros que a entidade espera obter a partir do uso contínuo do ativo.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno 106_PF_016_01 (Conhecimentos Específicos - Bloco III, cargo Agente de Polícia Federal) da PF 2025; gabarito conferido em 106_PF_016_01 (CARGO 16). Base normativa (CPC 00 R2) ainda não conferida individualmente na fonte oficial — aguardando revisão item a item antes de content_status=active.$q$,'específica')
), editions as (
  select id,contest_year from public.syllabus_editions
  where contest_name='Polícia Federal' and role_name='Agente de Polícia Federal' and contest_year=2025
), resolved as (
  select imported.*, question_source.id question_source_id, answer_source.id answer_key_source_id, topic.id syllabus_topic_id
  from imported
  join editions on editions.contest_year=imported.exam_year
  join public.syllabus_topics topic on topic.edition_id=editions.id and topic.discipline=imported.subject and topic.topic_order=1
  join public.content_sources question_source on question_source.title=(
    case imported.source_block
      when 'CB2' then 'Prova objetiva PF 2025 - Bloco I Comum (CB2)'
      when 'CG1' then 'Prova objetiva PF 2025 - Bloco II Comum TI (CG1)'
      else 'Prova objetiva PF 2025 - Agente de Polícia Federal (específica)'
    end
  )
  join public.content_sources answer_source on answer_source.title=(
    case imported.source_block
      when 'CB2' then 'Gabarito definitivo PF 2025 - Bloco I Comum (CB2)'
      when 'CG1' then 'Gabarito definitivo PF 2025 - Bloco II Comum TI (CG1)'
      else 'Gabarito definitivo PF 2025 - Agente de Polícia Federal (específica)'
    end
  )
)
insert into public.official_exam_questions (
  question_source_id,answer_key_source_id,syllabus_topic_id,contest_name,career_name,exam_board,exam_year,item_number,subject,
  question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,
  context_review_required,review_note
)
select question_source_id,answer_key_source_id,syllabus_topic_id,'Polícia Federal','Agente de Polícia Federal','CEBRASPE',exam_year,item_number,subject,
  question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,
  context_review_required,review_note
from resolved
on conflict (contest_name,career_name,exam_year,item_number) do nothing;
